// Visualization of symmetries to simpify SDFs
// abs(p) is a big benefit.
// "twizzle" seems a nice name for a little additional step.
// Twizzle benefits might only be for exact SDFs - still struggling with that...these are inexact SDFs

#define max4(A,B,C,D) max(max(A,B),max(C,D))
#define max3(A,B,C) max(max(A,B),C)

#define twizzle(p) \
    if ( p.y >= max(p.x,p.z) ) p = p.yzx; \
    else if ( p.z >= max(p.x,p.y) ) p = p.zxy;

float sdTetrahedron(vec3 p,float r) {
    twizzle(p) // abs(p) here makes something else nice
    return max3( /*-p.x+p.y+p.z,*/ p.x-p.y+p.z, p.x+p.y-p.z, -p.x-p.y-p.z)/sqrt(3.) - r;
}

float sdCube(vec3 p,float r) {
    p = abs(p); twizzle(p) // so similar that a compiler might generate the same code...
    return p.x - r;
    //return max3(p.x,p.y,p.z) - r;
}

float sdOctahedron(vec3 p,float r) {
    p = abs(p); // twizzle(p) no benefit here
    return (p.x+p.y+p.z)/sqrt(3.) - r;
}

#define PHI 1.6180339887

float sdDodecahedron(vec3 p,float r) {
    p = abs(p); twizzle(p)
    return max( /* p.y+p.z*PHI, */ p.z+p.x*PHI, p.x+p.y*PHI )/sqrt(2.+PHI) - r;
}

float sdIcosahedron(vec3 p,float r) {
    p = abs(p); twizzle(p)
    return max3( p.x+p.y+p.z, /* p.y/PHI+p.z*PHI, */ p.z/PHI+p.x*PHI, p.x/PHI+p.y*PHI )/sqrt(3.) - r;
}    

// Circumscribed sphere radius ratio to Inscribed sphere radius (thanks spalmer)
#define CircSphTetrahedron  (1./3.)
#define CircSphCube         sqrt(1./3.)
#define CircSphOctahedron   sqrt(1./3.)
#define CircSphDodecahedron sqrt(1./PHI)
#define CircSphIcosahedron  sqrt(1./PHI)

#define ROT2(ANG) mat2(cos(ANG),sin(ANG),-sin(ANG),cos(ANG))

#define PI 3.141592653589793
#define TAU (2.*PI)

vec3 Spin(float tim,vec3 p) {
tim=0.;
   tim += iTime;
   p.xz *= ROT2(tim*.75+iMouse.x*TAU/iResolution.x);
   p.yz *= ROT2(tim*.25+iMouse.y*TAU/iResolution.y);
   p.yx *= ROT2(tim*.5);
   return p;
}

#define sin1(X) (.5+.5*sin(X))
#define sinab(X,A,B) (sin1(X)*(B-A)+A)

#define min3(A,B,C) min(min(A,B),C)

bool hide;
int ccol;
float off;
vec3 Split(int opt,vec3 p) {
   vec3 save = p;
   p = abs(p);
   off = max(0.,sinab(iTime*.5-PI/2.,-.5,1.));
   hide = false;
   //if ( opt != 1 )  // option for Tetra to skip "physical" split
   {
     p -= off;
     hide = p.x < 0. || p.y < 0. || p.z < 0.;
     p = max(p,vec3(0));
   }
   ccol = 0;
   if ( off > 0. && ! hide ) {
     if ( p.x > max(p.y,p.z) )
       ccol = 1;
     else if ( p.y > max(p.x,p.z) )
       ccol = 2;
     else
       ccol = 3;
     if ( min3(abs(p.x-max(p.y,p.z)),abs(p.z-max(p.x,p.y)),abs(p.y-max(p.x,p.z))) < off*.2 )
       hide = true;
     }
   return p * sign(save);
}

#define T(SDF) if ( (tmp = SDF) < hit.x ) ccol2=ccol, hide2=hide, hit = vec2(tmp,clr); clr += 1.;

bool hide2;
int ccol2;
vec2 Dist(vec3 pt) {
    vec2 hit = vec2(100000,0);
    float tmp, clr = 0.;

    float SZ=6.;

    clr = 0.;

    T(sdTetrahedron( Split(1,Spin(2.,pt-vec3(-15,7,9))),SZ*CircSphTetrahedron));
    T(sdCube(        Split(0,Spin(2.,pt-vec3(0,7,9))),SZ*CircSphCube));
    T(sdOctahedron(  Split(0,Spin(3.,pt-vec3(15,7,9))),SZ*CircSphOctahedron));
    T(sdDodecahedron(Split(0,Spin(4.,pt-vec3(-10,-7,9))),SZ*CircSphDodecahedron));
    T(sdIcosahedron( Split(0,Spin(4.,pt-vec3(10,-7,9))),SZ*CircSphIcosahedron));

    T(pt.z+200.);
    return hit;
}

vec4 March(vec3 beg,vec3 dir) {
    float dist = 0.;
    vec3 pos;
    #define LIMIT 100
    for ( int stps = 0; stps <= LIMIT; ++stps ) {
        pos = beg + dir * dist;
        vec2 obj = Dist( pos );
        dist += obj.x;
        if ( obj.x < .001 || stps == LIMIT ) return vec4( pos, obj.y );
    }
    return vec4( pos, 90. );
}

vec3 Normal(vec3 pt) {
    float delta = .4;
    vec3 norm = Dist(pt).x - vec3(
        Dist(pt-vec3(delta, 0., 0.)).x, 
        Dist(pt-vec3( 0.,delta, 0.)).x, 
        Dist(pt-vec3( 0., 0.,delta)).x );
    return normalize( norm );
}

float pow2n(float i,int n)
{
  while ( n-- > 0 ) i *= i;
  return i;
}

void mainImage( out vec4 O, vec2 U )
{
    vec2 R = iResolution.xy;
    vec2 uv = (U+U-R) / min(R.x,R.y);  // -1 ... +1
    uv /= 5.;

    vec3 cam = vec3( 0, 0, -64.);
    vec3 camdir = normalize( vec3( uv, 1. ) );

    vec4 hit = March( cam, camdir );
    vec3 norm = Normal(hit.xyz);

    vec3 light = vec3( 0, 10, -10 );
    vec3 dir = normalize( light - hit.xyz );
    float difu = dot( norm, dir );

    difu = .5 + .5*difu;

    #define col4(X) ( .5 + .3 * sin( vec4(0,21,23,0) + (X) ) )
    O = sqrt( col4(hit.w*.4) );
    if (ccol2==1) O=mix(O,vec4(1,0,0,1),off*.15); else
    if (ccol2==2) O=mix(O,vec4(0,1,0,1),off*.15); else
    if (ccol2==3) O=mix(O,vec4(0,0,1,1),off*.15);
    O *= difu + pow2n(difu,9);
    if ( hide2 ) O *= 0.;
}
